CREATE TABLE "public"."contact_messages" (
  "id"         bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "first_name" text   NOT NULL DEFAULT ''::text,
  "last_name"  text   NOT NULL DEFAULT ''::text,
  "email"      text   NOT NULL DEFAULT ''::text,
  "message"    text   NOT NULL DEFAULT ''::text,
  CONSTRAINT "contact_messages_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."contact_messages"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anon can insert in contact_messages" ON "public"."contact_messages"
  FOR INSERT
  TO "anon", "authenticated"
  WITH CHECK (true);

REVOKE ALL ON SEQUENCE "public"."contact_messages_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."contact_messages_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."contact_messages_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."contact_messages_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."contact_messages_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."contact_messages_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."contact_messages_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."contact_messages_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."contact_messages" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."contact_messages" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."contact_messages" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."contact_messages" TO "service_role";

